<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {BookOpen,Timer,ArrowLeft,CheckCircle2} from 'lucide-vue-next';
const props=defineProps({specialty:Object});
const base=import.meta.env.VITE_CONTENT_API;
const exams=ref([]),questions=ref([]),answers=ref({}),current=ref(0),mode=ref(''),revealed=ref(false),result=ref(null),busy=ref(false),error=ref(''),attempt=ref(null),remaining=ref(0);
let interval, deadline=0, saveQueue=Promise.resolve(), autoSubmitted=false;
const question=computed(()=>questions.value[current.value]);
const clock=computed(()=>`${Math.floor(remaining.value/60).toString().padStart(2,'0')}:${(remaining.value%60).toString().padStart(2,'0')}`);
async function api(path,body,token){const r=await fetch(base+path,{method:body?'POST':'GET',headers:{Accept:'application/json',...(body?{'Content-Type':'application/json'}:{}),...(token?{'X-Attempt-Token':token}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});if(!r.ok)throw new Error('تعذّر إتمام الطلب. تحقق من الاتصال ثم أعد المحاولة.');return r.json();}
onMounted(async()=>{try{exams.value=await api(`/exams?specialty_id=${props.specialty.database_id}`);}catch(e){error.value=e.message;}interval=setInterval(()=>{if(mode.value==='exam'&&!result.value&&attempt.value){remaining.value=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(!remaining.value&&!busy.value&&!autoSubmitted){autoSubmitted=true;submit();}}},1000);});
onUnmounted(()=>clearInterval(interval));
async function start(exam){busy.value=true;error.value='';autoSubmitted=false;try{answers.value={};current.value=0;result.value=null;revealed.value=false;if(exam){const d=await api(`/exams/${exam.id}/attempts`,{});attempt.value=d;questions.value=d.questions;deadline=Date.parse(d.expires_at);remaining.value=Math.max(0,Math.ceil((deadline-Date.now())/1000));mode.value='exam';}else{questions.value=await api(`/specialties/${props.specialty.database_id}/practice`);mode.value='practice';}}catch(e){error.value=e.message;}finally{busy.value=false;}}
function choose(option){if(revealed.value)return;answers.value={...answers.value,[question.value.id]:option};if(mode.value==='exam'){const id=question.value.id;saveQueue=saveQueue.then(()=>api(`/attempts/${attempt.value.id}/answers`,{question_id:id,option},attempt.value.token)).catch(e=>{error.value=e.message+' قد لا تكون آخر إجابة محفوظة.';});}}
async function submit(){busy.value=true;error.value='';try{await saveQueue;if(mode.value==='exam'){result.value=await api(`/attempts/${attempt.value.id}/submit`,{answers:answers.value},attempt.value.token);}else{result.value={score:questions.value.filter(q=>answers.value[q.id]===q.correct_option).length,total:questions.value.length,correction:questions.value.map(q=>({...q,answer:answers.value[q.id]??null}))};}}catch(e){error.value=e.message;}finally{busy.value=false;}}
function next(){if(current.value===questions.value.length-1){submit();return;}current.value++;revealed.value=false;}
</script>
<template>
<p v-if="error" class="notice" role="alert">{{error}}</p>
<div v-if="!mode" class="mode-grid"><article class="mode-card"><BookOpen :size="42"/><h2>تدريب مع التصحيح</h2><p>أسئلة التخصص مع شرح الإجابات.</p><button class="button" :disabled="busy" @click="start()">ابدأ التدريب</button></article><article class="mode-card dark"><Timer :size="42"/><h2>الامتحانات التجريبية</h2><p v-if="!exams.length">لا توجد امتحانات منشورة لهذا التخصص بعد.</p><button v-for="exam in exams" :key="exam.id" class="button yellow" :disabled="busy" @click="start(exam)">{{exam.title}} · {{exam.duration_minutes}} دقيقة</button></article></div>
<div v-else-if="result"><div class="result"><CheckCircle2 :size="44"/><h2>النتيجة</h2><strong class="score">{{result.score}} / {{result.total}}</strong></div><article v-for="q in result.correction" :key="q.id" class="review"><h3>{{q.prompt}}</h3><p>إجابتك: {{q.answer===null?'لم تُجب':q.options[q.answer]}}</p><p><strong>الإجابة الصحيحة: {{q.options[q.correct_option]}}</strong></p><p>{{q.explanation}}</p></article><button class="button" @click="mode='';attempt=null;result=null">العودة إلى الاختيارات</button></div>
<div v-else-if="question" class="server-quiz"><div class="quiz-top"><span>السؤال {{current+1}} من {{questions.length}}</span><span v-if="mode==='exam'" dir="ltr" class="clock">{{clock}}</span></div><h2 class="question">{{question.prompt}}</h2><fieldset><legend class="sr-only">اختر إجابة</legend><label v-for="(option,i) in question.options" :key="i" class="answer" :class="{selected:answers[question.id]===i,correct:revealed&&i===question.correct_option}"><input type="radio" :name="`server-${question.id}`" :checked="answers[question.id]===i" :disabled="busy||revealed" @change="choose(i)">{{option}}</label></fieldset><div v-if="revealed" class="explanation"><strong>الإجابة الصحيحة: {{question.options[question.correct_option]}}</strong><p>{{question.explanation}}</p></div><div class="quiz-actions"><button v-if="mode==='practice'&&!revealed" class="button" :disabled="answers[question.id]===undefined||busy" @click="revealed=true">تحقّق من الإجابة</button><button v-else class="button" :disabled="busy" @click="next">{{current===questions.length-1?'عرض النتيجة':'السؤال التالي'}} <ArrowLeft :size="18"/></button><button v-if="mode==='exam'" class="text-button" :disabled="busy" @click="submit">تسليم الامتحان</button></div></div>
<div v-else class="empty"><p>لا توجد أسئلة منشورة لهذا التخصص بعد.</p><button class="button" @click="mode=''">العودة</button></div>
</template>
